package com.pranit.productsupport.bff.config;import java.io.IOException;import java.util.UUID;import org.slf4j.MDC;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import jakarta.servlet.FilterChain;import jakarta.servlet.ServletException;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;@Component public class RequestIdFilter extends OncePerRequestFilter{@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String id=r.getHeader("X-Request-Id");if(id==null||!id.matches("[A-Za-z0-9._-]{1,80}"))id=UUID.randomUUID().toString();s.setHeader("X-Request-Id",id);MDC.put("requestId",id);try{c.doFilter(r,s);}finally{MDC.remove("requestId");}}}
